import type { RunRoleOptions, Role, InputBundle } from './types.js';
function promptFor(o: Pick<RunRoleOptions, 'role' | 'inputBundle'>): string {
    const criteria = workflowCriteriaManifest(o.inputBundle.context);
    if (criteria && (criteria.role !== o.role || createHash('sha256').update(o.inputBundle.contracts).digest('hex') !== (o.inputBundle.context.workflowCriteria as {operatingSha256:string}).operatingSha256))
        throw Error('Original workflow criteria operating input changed');
    const sources = o.inputBundle.sources.map(({ content, ...metadata }) => ({ ...metadata, lineCount: content.split('\n').length,
        ...(sourceScopeVersion(o.inputBundle.context) === 2 ? { assessedLineCount: assessedLineCount(content, o.inputBundle.context) } : {}) }));
    const body = { requirements: o.inputBundle.requirements, contracts: o.inputBundle.contracts, context: o.inputBundle.context, sources, ...(o.inputBundle.sourceCatalogue ? { sourceDiscovery: sourceCatalogueHeader(o.inputBundle.sourceCatalogue, o.inputBundle.context) } : {}), requiredScope: o.inputBundle.requiredScope };
    const supplied = o.inputBundle.sources.filter(s => s.exposeInPrompt).map(s => `\nSOURCE ${JSON.stringify({ id: s.id })}\n${s.content}\nEND SOURCE\n`).join('');
    const render = (context: Record<string, unknown>) => `${roleInputPrefix(o.role, context)}${JSON.stringify({ ...body, context })}\n${supplied}`;
    const canonical = render(o.inputBundle.context);
    if (Buffer.byteLength(canonical) > 2 * 1024 * 1024)
        throw new Error('Role prompt exceeds2MiB profile');
    const context = presentPlanningDomains(o.role, presentMetadataIdentities(o.role, presentFindingBodies(presentHistoricalRequirements(o.inputBundle.context, o.role), o.role)), o.inputBundle.context.planVersion);
    const prompt = context === o.inputBundle.context ? canonical : render(context);
    if (Buffer.byteLength(prompt) > 2 * 1024 * 1024) throw new Error('Role prompt exceeds2MiB profile');
    return prompt;
}
