/** One Native recipe for fresh preallocation and execution. Historical requests
 * retain their recorded carrier; never reconstruct them from this default. */
export function nativeRoleFraming(role: Role, inputBundle: InputBundle, requestId: string, maxNativeTurns: number,
    requestedCarrier?: 'formatter/v1' | 'assistant-json/v1' | 'tool-submission/v1', maxProviderRequests?: number) {
    const { context } = inputBundle;
    const reviewResolution = reviewResolutionInput(role, context);
    const submission = role === 'planner' && context.stage === 'planning' ||
        role === 'challenger' && context.stage === 'planning-challenge' ||
        role === 'implementer' && context.stage === 'implementation' ||
        role === 'repairer' && context.stage === 'substantive-repair' ||
        role === 'adjudicator' && (context.stage === 'planning-adjudication' ||
            (reviewResolution?.version ?? 0) >= 3 && subjectActionInputVersion(role, context) === 2);
    const carrier = requestedCarrier ?? (submission ? 'tool-submission/v1' : reviewResolution ? 'assistant-json/v1' : 'formatter/v1');
    if (!['formatter/v1','assistant-json/v1','tool-submission/v1'].includes(carrier)) throw Error('NATIVE_RESPONSE_CARRIER_UNSUPPORTED');
    if (carrier === 'tool-submission/v1' && !submission) throw Error('NATIVE_SUBMISSION_ROLE_UNSUPPORTED');
    const framing = roleFraming(role,inputBundle,carrier === 'tool-submission/v1' ? 'tool-submission' : carrier === 'formatter/v1',
        maxProviderRequests === undefined ? undefined : {maxProviderRequests,maxNativeTurns});
    const binding = {launchId:requestId,role,nativeEvidencePolicy:nativeEvidencePolicy.id,stage:typeof inputBundle.context.stage === 'string' && inputBundle.context.stage ? inputBundle.context.stage : 'unspecified',
        inputDigest:createHash('sha256').update(carrier === 'formatter/v1' ? JSON.stringify(inputBundle) : framing.prompt).digest('hex')};
    const intent: StructuredOutputIntent = freezeStructuredOutput({
        ...(carrier === 'formatter/v1' ? {version:1 as const} : carrier === 'tool-submission/v1' ? {version:3 as const,carrier:'tool-submission/v1' as const} : {version:2 as const,carrier:'assistant-json/v1' as const}),
        requestId,binding,schema:framing.schema,maxNativeTurns,
    });
    return {...framing,schema:intent.schema,intent};
}
